import 'package:flutter/material.dart';
import '../../core/network/api_client.dart';
import '../../core/theme/app_theme.dart';
import '../../core/widgets/app_widgets.dart';

class AmbulancePage extends StatefulWidget { const AmbulancePage({super.key}); @override State<AmbulancePage> createState() => _AmbulancePageState(); }
class _AmbulancePageState extends State<AmbulancePage> {
  final api = ApiClient(); Map<String, dynamic>? ambulance; bool loading = true;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async { try { final r = await api.get('/ambulances/mine'); if (mounted && r is List && r.isNotEmpty) setState(() => ambulance = Map<String, dynamic>.from(r.first)); } catch (_) {} finally { if (mounted) setState(() => loading = false); } }
  @override Widget build(BuildContext c) => Scaffold(appBar: AppBar(title: const Text('My Ambulance', style: TextStyle(fontWeight: FontWeight.w900))), body: loading ? const Center(child: CircularProgressIndicator()) : ListView(padding: const EdgeInsets.all(18), children: [PageHeader(eyebrow: 'Vehicle', title: 'My ambulance', subtitle: 'Live vehicle status and operational details.'), const SizedBox(height: 16), SurfaceCard(gradient: const [Color(0xFF0D2342), Color(0xFF173F70)], child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Container(height: 150, width: double.infinity, decoration: BoxDecoration(borderRadius: BorderRadius.circular(20), color: const Color(0x221ffffff), image: const DecorationImage(image: AssetImage('assets/ambulance_hero.png'), fit: BoxFit.cover))), const SizedBox(height: 15), Text(ambulance?['vehicle_number']?.toString() ?? 'AMBULANCE', style: const TextStyle(color: Colors.white, fontSize: 27, fontWeight: FontWeight.w900)), const SizedBox(height: 6), StatusChip((ambulance?['status']?.toString() ?? 'AVAILABLE'), color: AppTheme.green)])), const SizedBox(height: 14), SurfaceCard(child: Column(children: [_line(Icons.local_gas_station_rounded, 'Fuel status', '80% ready', AppTheme.green), const Divider(height: 1), _line(Icons.location_on_rounded, 'Current location', 'Live GPS from ambulance', AppTheme.blue), const Divider(height: 1), _line(Icons.build_circle_outlined, 'Service status', 'Operational', AppTheme.purple), const Divider(height: 1), _line(Icons.medical_services_outlined, 'Emergency equipment', 'Configured', AppTheme.red)])), const SizedBox(height: 14), PrimaryButton(label: 'View live location', icon: Icons.map_rounded, background: AppTheme.blue, onPressed: () => Navigator.pushNamed(context, '/location'))]));
  Widget _line(IconData i, String a, String b, Color color) => ListTile(contentPadding: EdgeInsets.zero, leading: Container(width: 40, height: 40, decoration: BoxDecoration(color: color.withValues(alpha: .09), borderRadius: BorderRadius.circular(13)), child: Icon(i, color: color)), title: Text(a, style: const TextStyle(color: AppTheme.ink, fontWeight: FontWeight.w800)), subtitle: Text(b, style: const TextStyle(color: AppTheme.muted, fontSize: 11)));
}
